package net.officefloor.hq.app.role;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/roles")
@Validated
public class RoleController {

    /** What the screen is told about a role set on the sheet. */
    public record RoleView(String user, String role) {

        static RoleView of(Role role) {
            return new RoleView(role.getUserName(), role.getRole());
        }
    }

    /** A role as entered on the form: a user name and one of the roles. */
    public record RoleForm(
            @NotBlank @Size(max = 200) String user,
            @NotNull @Pattern(regexp = Role.CLERK + "|" + Role.STEWARD) String role) {
    }

    private final RoleService service;

    public RoleController(RoleService service) {
        this.service = service;
    }

    /** The roles set on the sheet, by user name; a name not listed is a clerk. */
    @GetMapping
    public List<RoleView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(RoleView::of).toList();
    }

    /** Set a user name's role on the sheet. */
    @PutMapping
    public RoleView set(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RoleForm form) {
        return RoleView.of(service.set(sheetId, SignedIn.name(user), form.user().trim(), form.role()));
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet: clerk or steward. A name with no role set is a clerk. */
@Entity
@Table(name = "sheet_role")
public class Role {

    /** The role of any name that has none set. */
    public static final String CLERK = "clerk";

    /** The role that may settle any claim, whatever the clerk limit, and approves or rejects a PENDING one. */
    public static final String STEWARD = "steward";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "role", nullable = false)
    private String role;

    protected Role() {
    }

    public Role(String sheetId, String userName, String role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RoleRepository extends JpaRepository<Role, Long> {

    /** The roles set on the sheet, by user name. */
    List<Role> findBySheetIdOrderByUserNameAsc(String sheetId);

    /** The role set for a user name on the sheet. */
    Optional<Role> findBySheetIdAndUserName(String sheetId, String userName);
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles user names have on a sheet: listed, set and looked up. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetService sheets;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role a user name has on the sheet: the one set for it, else clerk. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /**
     * Whether a user name may take an action (open, settle, void, reassign, close or reopen) on the
     * sheet: its role is among those the sheet's permission matrix sets for it, else its standing rule.
     */
    @Transactional(readOnly = true)
    public boolean permits(String sheetId, String userName, String action) {
        return sheets.load(sheetId).permits(action, roleOf(sheetId, userName));
    }

    /** Set the role of a user name on the sheet, replacing any it had. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.lock(sheetId);
        Role saved = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        saved.setRole(role);
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}
